use xiom.io;

use xiom.string;
type BankAccount = {
  balance: Float64;
}

fn BankAccount.withdraw(self, amount: Float64) -> Float64
  requires: amount > 0.0;
  requires: amount <= self.balance;
  ensures: result == self.balance - amount;
{
  return self.balance - amount;
}

fn main() -> Int {
  let account = BankAccount { balance: 200.0 };
  let new_bal = account.withdraw(50.0);
  io.println(string.float_to_str(new_bal));
  return 0;
}
